import{_ as a,C as o,o as r,c as n,j as e,a as i,E as h,a6 as p}from"./chunks/framework.CCKCzdWs.js";const d="/screenshots/desktop-run-live.png",l="/screenshots/desktop-run-live-code.png",b=JSON.parse(`{"title":"Desktop app runs","description":"Pause, step and watch the Playwright runs the desktop app starts, from its Local runs tray: each worker's test, its page live as it runs and at a stop, a pick on its image, the code a stop makes, to copy, a run shared live with your team, and the same runs for a coding agent.","frontmatter":{"title":"Desktop app runs","description":"Pause, step and watch the Playwright runs the desktop app starts, from its Local runs tray: each worker's test, its page live as it runs and at a stop, a pick on its image, the code a stop makes, to copy, a run shared live with your team, and the same runs for a coding agent.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/desktop-runs.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/desktop-runs.html"}],["meta",{"property":"og:title","content":"Desktop app runs | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Pause, step and watch the Playwright runs the desktop app starts, from its Local runs tray: each worker's test, its page live as it runs and at a stop, a pick on its image, the code a stop makes, to copy, a run shared live with your team, and the same runs for a coding agent."}]]},"headers":[],"relativePath":"features/desktop-runs.md","filePath":"features/desktop-runs.md","lastUpdated":1794492047000}`),c={name:"features/desktop-runs.md"};function u(g,t,w,f,m,k){const s=o("Needs");return r(),n("div",null,[t[0]||(t[0]=e("h1",{id:"desktop-app-runs",tabindex:"-1"},[i("Desktop app runs "),e("a",{class:"header-anchor",href:"#desktop-app-runs","aria-label":'Permalink to "Desktop app runs"'},"​")],-1)),h(s,{desktop:"",fixtures:""}),t[1]||(t[1]=p('<p>Every Playwright run the <a href="./desktop.html">desktop app</a> starts names the app as its hub: a <strong>Re-run</strong> of tests, a reproduction, a bisect step, a <a href="./flake-lab.html">Flake Lab</a> run and a bug report&#39;s run. Its <strong>Local runs</strong> tray shows each worker of the run beside its output, and steers the test as the editor does: <a href="./editor-run-control.html">Pause and step from the editor</a>. Nothing leaves your machine unless you <a href="#share-live">share a run live</a>.</p><h2 id="each-worker" tabindex="-1">Each worker <a class="header-anchor" href="#each-worker" aria-label="Permalink to &quot;Each worker&quot;">​</a></h2><p>While a run goes on, the tray shows each worker&#39;s test, project and attempt, and whether it runs. <strong>Pause</strong> stops the test before its next call that acts on or checks the page. A test also stops at a <code>page.pause()</code>, and a headed one shows Piwi&#39;s <a href="./editor-breakpoints.html#pause-a-run">pause bar</a> there.</p><p>At a stop, the tray says why the test stopped, the call about to run (<strong>Next</strong>) and its place in your code (<strong>At</strong>), with an image of the page. <strong>Resume</strong> lets the test go on, <strong>Step</strong> runs one call and stops before the next, <strong>Finish</strong> runs it to its end without stopping again, and <a href="./end-the-test.html"><strong>End the test</strong></a> skips the rest.</p><p>A run of several workers shows one at a time, behind a tab each (<strong>worker 2</strong>) marked with its state. A new stop takes the tab from a worker that runs unwatched, and <strong>Resume</strong> or <strong>End the test</strong> there moves it to the next stopped test. <strong>Pause all</strong> and <strong>Resume all</strong> steer every worker at once.</p><p><strong>Hold failures</strong>, on each running run, holds a failing test at its line: <strong>Failed at</strong>, its error under it, and <strong>Resume</strong> to let it end as it failed. It is on from the start for <strong>Reproduce</strong>, which runs to show you the failure, and a run started with it on; <strong>Run again</strong> keeps it. It is <a href="/guide/concepts.html#hold-failures">the run&#39;s own</a>, off again as the app&#39;s last window closes. A run <a href="/guide/concepts.html#hold-failures">nobody attends</a> never holds one, and its switch says why.</p><figure><img src="'+d+'" alt="The Local runs tray of the desktop app: a running run with its Hold failures switch, and its checkout test stopped at its page.pause() before its click on Pay now, its page watched live with Interact on, with Resume, Step, Finish, Assert a region and Mock a request"><figcaption>A run the desktop app started, stopped at a <code>page.pause()</code> and watched live.</figcaption></figure><p>The tray opens at each stop, where a headless test waits for you. With the window in the background, the system tells you of a failure or a <code>page.pause()</code>, never of a step or a pause you asked for. The window listens on every page, again as soon as it reloads while a run of the app goes on. On a page without the tray (an analytics dashboard in TV mode, an error page), the system tells you of every stop, whatever the window shows, and no failure is held; a <code>page.pause()</code>, a step or a breakpoint waits until the tray shows it again, or <a href="./runs-window.html">Piwi Picker&#39;s Runs window</a> or <a href="#for-agents">an agent</a> answers it. With no run of the app going on, the window stops listening, and a stop goes on at once.</p><h2 id="its-output" tabindex="-1">Its output <a class="header-anchor" href="#its-output" aria-label="Permalink to &quot;Its output&quot;">​</a></h2><p>Each run shows its output under its workers, in Playwright&#39;s terminal colors. <strong>Open the output in a separate window</strong>, the window button on the run, moves it to a window of its own, beside your editor or on another screen, still updating, with the run&#39;s <strong>Stop</strong>. Closing that window, or the same button, now <strong>Show the output here</strong>, brings it back; the window closes with the app.</p><h2 id="watch-live" tabindex="-1">Watch live <a class="header-anchor" href="#watch-live" aria-label="Permalink to &quot;Watch live&quot;">​</a></h2><p><strong>Watch</strong>, on a running worker in the tray or its test on the run&#39;s page, shows its page as the test runs and at each stop, until you turn it off; at a stop, <strong>Interact</strong> sends your input there as with <strong>Watch live</strong>. Between two images, and with an older reporter: <a href="./watch-running-test.html">Watch a running test</a>.</p><p><strong>Watch live</strong> shows the stopped page as it paints, in place of its image, and stays on for the worker&#39;s next stops until you turn it off. <a href="./watch-running-test.html#interact"><strong>Interact</strong></a>, beside it, sends your clicks, the wheel and your keys on the view to the page; <code>Tab</code> leaves the view unless a click into it took the keyboard. Nothing keeps the <a href="/guide/concepts.html#watch-share-live">frames</a>.</p><p><strong>Pause and watch</strong>, on a running test of the run&#39;s page in the app (<strong>Open run #N</strong> on the run in the tray), pauses the test as <strong>Pause</strong> does and watches its worker: the tray opens at the stop, the page live, and the row says where it stopped, with <strong>Show its page</strong> to open the tray on it again.</p><p><strong>Pick on the image</strong> (Playwright 1.60 or later), or a <code>Shift</code>+click on the image or the view, names the element under the pointer: its locator shows under the test, with <strong>Copy</strong>.</p><p>Under a watched page, from a reporter newer than 0.68.0, the tray shows what pixels cannot, as the editor does (<a href="./watch-running-test.html#beside-the-image">beside the image</a>): <strong>Why it waits</strong>, <strong>Events</strong>, <strong>Text</strong> (<strong>Show the page&#39;s text</strong> reads it at each test, secret fields hidden, then follows the test&#39;s trace) and <strong>Filmstrip</strong> (a click enlarges an image, with its call), kept in memory alone. <strong>Open the trace so far</strong>, in a watched page&#39;s head, opens Playwright&#39;s trace viewer on the running test&#39;s trace up to now, on your machine, with a reporter newer than 0.68.0: <a href="./watch-running-test.html#open-the-trace-so-far">Watch a running test</a>.</p><h2 id="code-to-copy" tabindex="-1">Code to copy <a class="header-anchor" href="#code-to-copy" aria-label="Permalink to &quot;Code to copy&quot;">​</a></h2><p>The app holds no editor, so the code a stop makes comes to the tray, under <strong>Code from the runs</strong>, rather than into your file:</p><ul><li><strong>Assert a region</strong> picks a region of the page, once you watch a headless stop live: its ARIA snapshot becomes a <code>toMatchAriaSnapshot</code> check.</li><li><strong>Mock a request</strong> lists the page&#39;s fetch and XHR responses, credentials hidden: the one you choose becomes a <code>page.route</code>, with what to review in it.</li><li><strong>A locator picked</strong>, on the image or with the pause bar&#39;s <strong>Pick a locator</strong>, shows with the line it was picked for.</li></ul><p>Each code shows the line it goes above and, apart, its import lines, each with <strong>Copy</strong>, made from the file as it is on disk in the folder linked to the project.</p><figure><img src="'+l+'" alt="Code from the runs in the desktop app&#39;s tray: a mocked request, the page.route call to write above tests/checkout.spec.ts:18, with Copy"><figcaption>A mocked request, as code to copy above the stopped line.</figcaption></figure><h2 id="share-live" tabindex="-1">Share live <a class="header-anchor" href="#share-live" aria-label="Permalink to &quot;Share live&quot;">​</a></h2><p>A run that reports to your team&#39;s Piwi instance, as a <strong>Re-run</strong> in a folder whose <code>.env</code> or Playwright config names it does, can be shared there for a teammate to watch: <strong>Share live</strong>, above the run&#39;s workers, asks first the first time since the app started. Who sees what, and why a run cannot be shared: <a href="./share-live.html#from-the-desktop-app">Share a run live</a>.</p><h2 id="for-agents" tabindex="-1">For agents <a class="header-anchor" href="#for-agents" aria-label="Permalink to &quot;For agents&quot;">​</a></h2><p>The app&#39;s <a href="./mcp.html">MCP server</a> (its <strong>MCP server</strong> page connects your coding agent) serves these runs with the tools of <a href="./agent-run-control.html">Run control for agents</a>. An agent follows a run, pauses or steps it, and reads and acts on the stopped page as you can and no further: <a href="./agent-run-control.html#what-keeps-it-safe">what keeps it safe</a>.</p><p>The tray shows what it does: a stop it asked for says so (<strong>Paused by the agent</strong>), as does its first action at a stop. The code <code>code_write</code> makes (the steps it took, an assertion, or a locator for the stopped line) comes under <strong>Code from the runs</strong>, to copy, and back to the agent in its answer: no file is written. A run nobody attends is not served, so an agent sees no Flake Lab run, bisect or lab job.</p><p>The tray names who else is there: the tools that have a run open (<strong>Also open in Piwi Picker · An agent follows this run</strong>), who watches a worker&#39;s page, and who <a href="/guide/concepts.html#presence-driving-a-stop">drives a stop</a>: <strong>Take control</strong> from an agent, and <strong>Give back</strong>.</p><p>An agent pauses, steps or runs to a line only while the app&#39;s window is open, in the tray included: a headless stop goes on with no window to show it. A stop it asked for goes on two minutes after its last call, so a run never waits for an agent that left.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>No recording.</strong> <strong>Record here</strong>, and <strong>Pick</strong> and <strong>Assert</strong> in the test&#39;s window, end in an editor: run the test from VS Code or a JetBrains IDE to use them.</li><li><strong>A linked folder.</strong> A reproduction or a bisect step runs in a throwaway worktree, which no project links: its stops make no code.</li><li><strong>A file changed since the run started</strong> makes no code: run the test again.</li><li><strong>A reload forgets the tray&#39;s runs.</strong> A run still going shows among the app&#39;s other runs, without <strong>Hold failures</strong>: its failures go on, a reproduction&#39;s included.</li><li><strong>Run to cursor</strong> stays in the editor, which has the file.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./desktop.html">Desktop app</a>: what it runs, and how it links a project to its folder.</li><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the same stops, in VS Code and the JetBrains IDEs.</li><li><a href="./editor-stop-code.html">Code from a pause</a>: what each action writes.</li><li><a href="./runs-window.html#the-desktop-app-s-runs">Runs window</a>: Piwi Picker&#39;s window, paired with the app, for the same runs; the code it starts at their stops comes to this tray.</li><li><a href="./agent-run-control.html">Run control for agents</a>: the tools an agent steers the runs with.</li><li><a href="./flake-lab.html#in-the-desktop-app">Flake Lab</a>: <strong>Reproduce this flake</strong> and a flake-aware bisect, run by the app.</li></ul>',32))])}const v=a(c,[["render",u]]);export{b as __pageData,v as default};
